def _days_from_civil(y, m, d):
    """Days since 1970-01-01 (proleptic Gregorian)."""
    if m <= 2:
        y -= 1
        m += 12
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m - 3) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def _weekday(y, m, d):
    """Monday=0 ... Sunday=6."""
    return (_days_from_civil(y, m, d) + 4) % 7

def _days_in_month(y, m):
    if m == 2:
        leap = (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))
        return 29 if leap else 28
    return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]

def _date_to_utc_minutes(y, mo, d, h, mi, offset):
    days = _days_from_civil(y, mo, d)
    wall = days * 1440 + h * 60 + mi
    return wall - offset

def _rule_to_date(y, rule):
    mo, wk, wd, h, mi = rule
    dim = _days_in_month(y, mo)
    first_wd = _weekday(y, mo, 1)
    first_occ = 1 + ((wd - first_wd) % 7)
    if wk == -1:
        last_wd = _weekday(y, mo, dim)
        day = dim - ((last_wd - wd) % 7)
    else:
        day = first_occ + (wk - 1) * 7
    if not (1 <= day <= dim):
        raise ValueError("rule date out of month range")
    return y, mo, day, h, mi

