    e_rule = dst["end"]
    save = dst["save"]
    s_month = dst["start"][0]
    e_month = e_rule[0]
    end_year = Y if s_month < e_month else Y + 1
    y, mo, d, h, mi = _rule_to_date(end_year, e_rule)
    return _date_to_utc_minutes(y, mo, d, h, mi, std + save)

def _offset_at_utc(zone, t):
    std, dst = _validate_zone(zone)
    if dst is None:
        return std
    save = dst["save"]
    # approximate year of t
    y_approx = 1970 + t // 525960
    for Y in range(y_approx - 2, y_approx + 3):
        try:
            s = _start_utc(zone, std, dst, Y)
            e = _end_utc(zone, std, dst, Y)
            # DST interval: [s, e)
            if s <= t < e:
                return std + save
        except ValueError:
            continue
    return std

