    std, dst = _validate_zone(zone)
    if not isinstance(y, int) or not (1970 <= y <= 2100):
        raise ValueError("y out of range")
    if not isinstance(mo, int) or not isinstance(d, int):
        raise ValueError("mo, d must be ints")
    if not (0 <= h <= 23) or not (0 <= mi <= 59):
        raise ValueError("h, mi out of range")
    if fold not in (0, 1):
        raise ValueError("fold must be 0 or 1")
    try:
        datetime.date(y, mo, d)
    except ValueError:
        raise ValueError("Invalid date")

    wall = _days_from_civil(y, mo, d) * 1440 + h * 60 + mi
    offsets = [std]
    if dst is not None:
        offsets.append(std + dst["save"])

    valid = []
    for off in offsets:
        utc = wall - off
        if _offset_at_utc(zone, utc) == off:
            valid.append(utc)

    if not valid:
        raise ValueError("Wall time skipped")
    if len(valid) == 1:
        return valid[0]
    # Ambiguous: earlier is with dst (larger offset), later with std
    valid.sort()
    return valid[0] if fold == 0 else valid[1]

def next_transition(zone, t):
