# ---------- proleptic Gregorian calendar ----------

def _days_from_civil(y, m, d):
    """Days since 1970-01-01, proleptic Gregorian, any int year."""
    y -= m <= 2
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400                     # [0, 399]
    doy = (153 * (m + (m > 2 and -3 or 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def _days_in_month(y, mo):
    if mo == 12:
        return _days_from_civil(y + 1, 1, 1) - _days_from_civil(y, 12, 1)
    else:
        return _days_from_civil(y, mo + 1, 1) - _days_from_civil(y, mo, 1)

def _weekday_of_date(y, m, d):
    return (_days_from_civil(y, m, d) + 3) % 7   # Monday=0 ... Sunday=6

def _rule_day(y, mo, wk, wd):
    """Day of month for week-th weekday rule."""
    first = _days_from_civil(y, mo, 1)
    first_wd = (first + 3) % 7
    first_occ = 1 + (wd - first_wd) % 7
    last_day = _days_in_month(y, mo)
    if wk == -1:
        last_wd = (first + last_day - 1 + 3) % 7
        return last_day - (last_wd - wd) % 7
    else:
        day = first_occ + (wk - 1) * 7
        if not (1 <= day <= last_day):
            raise ValueError("rule date out of month")
        return day

def _transition_utc(y, rule, offset):
    mo, wk, wd, h, mi = rule
    day = _rule_day(y, mo, wk, wd)
    wall = _days_from_civil(y, mo, day) * 1440 + h * 60 + mi
    return wall - offset

# ---------- DST interval helpers ----------

def _start_utc(y, zone):
    return _transition_utc(y, zone["dst"]["start"], zone["std"])

def _end_utc(y, zone):
    return _transition_utc(y, zone["dst"]["end"], zone["std"] + zone["dst"]["save"])

def _is_dst(utc, zone):
    """True iff utc is inside a DST interval."""
    std = zone["std"]
    save = zone["dst"]["save"]
    s_rule = zone["dst"]["start"]
    e_rule = zone["dst"]["end"]

    # Approximate year containing utc; check a few around it.
    approx = 1970 + utc // 525960
    for Y in range(approx - 2, approx + 3):
        s = _start_utc(Y, zone)
        if s_rule[0] < e_rule[0]:
            e = _end_utc(Y, zone)
        else:
            e = _end_utc(Y + 1, zone)
        if s <= utc < e:
            return True
    return False

# ---------- public functions ----------

def local_to_utc(zone, y, mo, d, h, mi, fold=0):
    _validate_zone(zone)
    if not isinstance(y, int) or not (1970 <= y <= 2100):
        raise ValueError("y out of range")
    if not isinstance(mo, int) or not isinstance(d, int):
        raise ValueError("mo, d must be ints")
    if not (0 <= h <= 23) or not (0 <= mi <= 59):
        raise ValueError("h, mi out of range")
    if fold not in (0, 1):
        raise ValueError("fold must be 0 or 1")

    # Validate date
    if mo < 1 or mo > 12:
        raise ValueError("month out of range")
    if d < 1 or d > _days_in_month(y, mo):
        raise ValueError("invalid date")

    wall = _days_from_civil(y, mo, d) * 1440 + h * 60 + mi
    std = zone["std"]
    dst = zone["dst"]

    if dst is None:
        return wall - std

    save = dst["save"]
    utc_std = wall - std
    utc_dst = wall - (std + save)

    std_ok = not _is_dst(utc_std, zone)
    dst_ok = _is_dst(utc_dst, zone)

    if std_ok and dst_ok:
        return utc_dst if fold == 0 else utc_std
    elif dst_ok:
        return utc_dst
    elif std_ok:
        return utc_std
    else:
        raise ValueError("Wall time skipped")

def next_transition(zone, t):
    _validate_zone(zone)
    dst = zone["dst"]
    if dst is None:
        return None

    std = zone["std"]
    save = dst["save"]
    s_rule = dst["start"]
    e_rule = dst["end"]

    # Approximate year of t; search a wide enough range.
    approx = 1970 + t // 525960
    candidates = []
    for Y in range(approx - 3, approx + 4):
        # Start transition
        s = _transition_utc(Y, s_rule, std)
        if s > t:
            candidates.append((s, std + save))
        # End transition (always in year Y; for southern it ends a DST started in Y-1)
        e = _transition_utc(Y, e_rule, std + save)
        if e > t:
            candidates.append((e, std))

    if not candidates:
        return None
    candidates.sort()
    return candidates[0]

import collections

def simulate_rr(jobs, q):
    # Validation
    if not isinstance(jobs, list):
        raise ValueError("jobs must be a list")
    for j in jobs:
        if not isinstance(j, (list, tuple)) or len(j) != 3:
            raise ValueError("Each job must be a tuple/list of 3 elements")
        arr, burst, pri = j
        for v in (arr, burst, pri):
            if type(v) is bool or not isinstance(v, int):
                raise ValueError("Elements must be integers, not booleans")
        if arr < 0 or burst < 1:
            raise ValueError("arrival >= 0 and burst >= 1 required")

    if type(q) is bool or not isinstance(q, int) or q < 1:
        raise ValueError("q must be an integer >= 1")

    n = len(jobs)
    if n == 0:
        return []

    # indexed_jobs: (arrival, original_index, burst, priority)
    indexed_jobs = sorted(
        [(j[0], i, j[1], j[2]) for i, j in enumerate(jobs)],
        key=lambda x: (x[0], x[1])
    )

    queues = collections.defaultdict(collections.deque)
    results = [None] * n
    running = None  # dict: idx, rem, pri, start, q_used
    arr_idx = 0
    current_time = indexed_jobs[0][0]

    while arr_idx < n or running is not None:
        t = current_time

        # 1. Completion
        if running is not None and running['rem'] == 0:
            results[running['idx']] = (running['start'], t)
            running = None

        # 2. Arrivals at time t
        while arr_idx < n and indexed_jobs[arr_idx][0] == t:
            _, i, b, p = indexed_jobs[arr_idx]
            queues[p].append(i)
            arr_idx += 1

        # 3. Preemption / Quantum expiry
        if running is not None:
            if running['q_used'] == q:
                queues[running['pri']].append(running['idx'])
                running = None
            else:
                # Check for strictly better priority waiting
                has_better = False
                for p in queues:
                    if queues[p] and p < running['pri']:
                        has_better = True
                        break
                if has_better:
                    queues[running['pri']].appendleft(running['idx'])
                    running = None

        # 4. Start a job if CPU free
        if running is None:
            best_p = None
            for p in queues:
                if queues[p]:
                    if best_p is None or p < best_p:
                        best_p = p
            if best_p is not None:
                i = queues[best_p].popleft()
                running = {
                    'idx': i,
                    'rem': jobs[i][1],
                    'pri': jobs[i][2],
                    'start': t,
                    'q_used': 0
                }

        # 5. Advance time to next event
        if running is not None and running['rem'] > 0:
            # Possible next events:
            # - completion: t + rem
            # - quantum expiry: t + (q - q_used)
            # - next arrival (any unprocessed job)
            next_time = t + running['rem']
            next_time = min(next_time, t + (q - running['q_used']))
            if arr_idx < n:
                next_time = min(next_time, indexed_jobs[arr_idx][0])

            # If next event is the next arrival, we must not go past it
            # (arrivals are processed at the beginning of the next loop)
            duration = next_time - t
            if duration > 0:
                running['rem'] -= duration
                running['q_used'] += duration
                current_time = next_time
            else:
                # Should not happen, but guard against infinite loop
                break
        else:
            # CPU idle: jump to next arrival
            if arr_idx < n:
                current_time = indexed_jobs[arr_idx][0]
            else:
                break

    # Safety net (should not be needed)
    if running is not None:
        results[running['idx']] = (running['start'], current_time)

    return results

