        if running is None:
            best_p = None
            for p in queues:
                if queues[p]:
                    if best_p is None or p < best_p:
                        best_p = p
            if best_p is not None:
                i = queues[best_p].popleft()
                running = {
                    'idx': i,
                    'rem': jobs[i][1],
                    'pri': jobs[i][2],
                    'start': t,
                    'q_used': 0
                }

        # 5. Advance time efficiently
        if running is not None and running['rem'] > 0:
            p = running['pri']
            rem = running['rem']
            q_used = running['q_used']
            quantum_remaining = q - q_used

            # Does quantum expiry cause a context switch?
            # Only if there is another job in the same priority queue.
            queue_p_nonempty = bool(queues[p])

            # Earliest next arrival (any priority)
            next_arrival = indexed_jobs[arr_idx][0] if arr_idx < n else float('inf')

            completion_time = t + rem
            quantum_boundary = t + quantum_remaining if queue_p_nonempty else float('inf')

            next_time = min(completion_time, next_arrival, quantum_boundary)
            duration = next_time - t

            current_time = next_time
            running['rem'] -= duration

            if queue_p_nonempty:
                # We stopped at most at the quantum boundary, so q_used just increases
                running['q_used'] += duration
            else:
                # No same-priority competition: quantum boundaries are invisible
                # because the job is immediately restarted. Use modulo.
                running['q_used'] = (running['q_used'] + duration) % q

        else:
            # CPU idle: jump to next arrival
            if arr_idx < n:
                current_time = indexed_jobs[arr_idx][0]
            else:
                break

    # Safety net (should not be needed)
    if running is not None:
        results[running['idx']] = (running['start'], current_time)

    return results

