class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args

    def __eq__(self, other):
        return (isinstance(other, Type) and self.kind == other.kind
                and self.args == other.args)

    def __hash__(self):
        return hash((self.kind, self.args))


def apply_subs(t, subs):
    if t.kind == 'Var':
        if t.args[0] in subs:
            return apply_subs(subs[t.args[0]], subs)
        return t
    return Type(t.kind, *[apply_subs(a, subs) for a in t.args])


def occurs(id_, t):
    if t.kind == 'Var':
        return t.args[0] == id_
    return any(occurs(id_, a) for a in t.args)


def unify(t1, t2, subs):
    t1 = apply_subs(t1, subs)
    t2 = apply_subs(t2, subs)
    if t1 == t2:
        return

    if t1.kind == 'Var':
        if occurs(t1.args[0], t2):
            raise ValueError('Occurs check')
        subs[t1.args[0]] = t2
        return

    if t2.kind == 'Var':
        if occurs(t2.args[0], t1):
            raise ValueError('Occurs check')
        subs[t2.args[0]] = t1
        return

    if t1.kind != t2.kind:
        raise ValueError('Type mismatch')

    if t1.kind in ('Fun', 'Pair'):
        unify(t1.args[0], t2.args[0], subs)
        unify(t1.args[1], t2.args[1], subs)
        return

    raise ValueError('Type mismatch')


def free_vars(t, subs, bound=None):
    t = apply_subs(t, subs)
    res = set()

    def collect(tt):
        if tt.kind == 'Var':
            res.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)

    collect(t)
    if bound is not None:
        res -= bound
    return res


def env_free_vars(env, subs):
    free = set()
    seen = set()
    for scope in reversed(env):
        for name, (ty, qs) in scope.items():
            if name in seen:
                continue
            seen.add(name)
            free |= free_vars(ty, subs, qs)
    return free


def generalize(t, env, subs):
    t = apply_subs(t, subs)
    fv = free_vars(t, subs)
    env_fv = env_free_vars(env, subs)
    quantified = fv - env_fv
    return (t, quantified)


