def infer_term(term, state):
    if not isinstance(term, tuple):
        raise ValueError('Malformed term')
    if len(term) == 0:
        raise ValueError('Malformed term')

    tag = term[0]

    if tag == 'int':
        if len(term) != 2 or type(term[1]) is not int:
            raise ValueError('Malformed term')
        return Type('Int')

    if tag == 'bool':
        if len(term) != 2 or type(term[1]) is not bool:
            raise ValueError('Malformed term')
        return Type('Bool')

    if tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError('Malformed term')
        name = term[1]
        for scope in reversed(state.env):
            if name in scope:
                return instantiate(scope[name], state)
        raise ValueError('Unbound variable')

    if tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
            raise ValueError('Malformed term')
        name, body = term[1], term[2]
        v = state.fresh()
        arg_type = Type('Var', v)
        state.env.append({name: (arg_type, set())})
        body_type = infer_term(body, state)
        state.env.pop()
        return Type('Fun', arg_type, body_type)

    if tag == 'app':
        if len(term) != 3:
            raise ValueError('Malformed term')
        f, arg = term[1], term[2]
        f_type = infer_term(f, state)
        arg_type = infer_term(arg, state)
        ret = Type('Var', state.fresh())
        unify(f_type, Type('Fun', arg_type, ret), state.subs)
        return apply_subs(ret, state.subs)

    if tag == 'if':
        if len(term) != 4:
            raise ValueError('Malformed term')
        c, t, e = term[1], term[2], term[3]
        c_type = infer_term(c, state)
        t_type = infer_term(t, state)
        e_type = infer_term(e, state)
        unify(c_type, Type('Bool'), state.subs)
        unify(t_type, e_type, state.subs)
        return apply_subs(t_type, state.subs)

    if tag == 'pair':
        if len(term) != 3:
            raise ValueError('Malformed term')
        a, b = term[1], term[2]
        return Type('Pair', infer_term(a, state), infer_term(b, state))

    if tag == 'fst':
        if len(term) != 2:
            raise ValueError('Malformed term')
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t1, state.subs)

    if tag == 'snd':
        if len(term) != 2:
            raise ValueError('Malformed term')
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t2, state.subs)

    if tag == 'let':
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
            raise ValueError('Malformed term')
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer_term(e1, state)
        poly = generalize(e1_type, state.env, state.subs)
        state.env.append({name: poly})
        e2_type = infer_term(e2, state)
        state.env.pop()
        return apply_subs(e2_type, state.subs)

    if tag == 'letrec':
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
            raise ValueError('Malformed term')
        name, e1, e2 = term[1], term[2], term[3]
        v = state.fresh()
        rec_type = Type('Var', v)
        state.env.append({name: (rec_type, set())})
        e1_type = infer_term(e1, state)
        unify(rec_type, e1_type, state.subs)
        e1_type = apply_subs(e1_type, state.subs)
        poly = generalize(e1_type, state.env, state.subs)
        state.env[-1][name] = poly
        e2_type = infer_term(e2, state)
        state.env.pop()
        return apply_subs(e2_type, state.subs)

    raise ValueError('Malformed term')


def type_to_str(t, subs):
    t = apply_subs(t, subs)

    seen = []
    seen_set = set()

    def collect(tt):
        if tt.kind == 'Var':
            if tt.args[0] not in seen_set:
                seen.append(tt.args[0])
                seen_set.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)

    collect(t)

    names = []
    for i in range(len(seen)):
        if i < 26:
            names.append(chr(ord('a') + i))
        else:
            q, r = divmod(i - 26, 26)
            names.append(chr(ord('a') + r) + str(q + 1))

    var_map = {v: names[i] for i, v in enumerate(seen)}

    def show(tt):
        if tt.kind == 'Var':
            return var_map[tt.args[0]]
        if tt.kind == 'Int':
            return 'Int'
        if tt.kind == 'Bool':
            return 'Bool'
        if tt.kind == 'Fun':
            left = show(tt.args[0])
            right = show(tt.args[1])
            if tt.args[0].kind == 'Fun':
                left = f'({left})'
            return f'{left} -> {right}'
        if tt.kind == 'Pair':
            return f'({show(tt.args[0])}, {show(tt.args[1])})'
        return ''

    return show(t)


