import sys
from collections import deque

def phi_blocks(n, edges, entry, defs):
    # ---------- input validation ----------
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")

    defs_lists = {}
    for k, v in defs.items():
        try:
            it = iter(v)
        except TypeError:
            raise ValueError("defs values must be iterables of ints in 0..n-1")
        lst = []
        for node in it:
            if not isinstance(node, int) or isinstance(node, bool) or not (0 <= node < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")
            lst.append(node)
        defs_lists[k] = lst

    # ---------- graph ----------
    adj = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        pred[v].append(u)

    # ---------- reachable nodes ----------
    reachable = [False] * n
    q = [entry]
    reachable[entry] = True
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # ---------- DFS numbering / spanning tree ----------
    dfs_num = [-1] * n
    dfs_parent = [-1] * n
    vertex = []          # vertex[dfs_num] = node
    stack = [(entry, 0)]
    dfs_num[entry] = 0
    vertex.append(entry)
    dfs_parent[entry] = entry

    # Iterative DFS to avoid recursion limits
    while stack:
        u, idx = stack[-1]
        if idx < len(adj[u]):
            v = adj[u][idx]
            stack[-1] = (u, idx + 1)
            if dfs_num[v] == -1:
                dfs_num[v] = len(vertex)
                vertex.append(v)
                dfs_parent[v] = u
                stack.append((v, 0))
        else:
            stack.pop()

    N = len(vertex)

    # ---------- Lengauer-Tarjan dominators ----------
    semi = list(range(n))          # semidominator, stored as node
    idom = list(range(n))
    ancestor = [-1] * n
    label = list(range(n))         # DSU label
    bucket = [[] for _ in range(n)]

    def find(v):
        # iterative path compression
        path = []
        while ancestor[v] != -1:
            path.append(v)
            v = ancestor[v]
        root = v
        for x in reversed(path):
            if ancestor[x] == -1:
                continue
            # compress x
            if ancestor[ancestor[x]] != -1:
                # update label before compressing
                a = ancestor[x]
                if dfs_num[semi[label[a]]] < dfs_num[semi[label[x]]]:
                    label[x] = label[a]
                ancestor[x] = ancestor[a]
        return root

    def eval(v):
        if ancestor[v] == -1:
            return v
        find(v)
        return label[v]

    def link(v, w):
        ancestor[w] = v
        # label[w] is already w; no extra operation needed for this variant

    # Process vertices in reverse DFS order
    for i in range(N - 1, 0, -1):
        w = vertex[i]
        # compute semidominator
        for v in pred[w]:
            if dfs_num[v] != -1:
                u = eval(v)
                if dfs_num[semi[u]] < dfs_num[semi[w]]:
                    semi[w] = semi[u]

        bucket[vertex[dfs_num[semi[w]]]].append(w)

