def phi_blocks(n, edges, entry, defs):
    # ---------- input validation ----------
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")

    defs_lists = {}
    for k, v in defs.items():
        try:
            it = iter(v)
        except TypeError:
            raise ValueError("defs values must be iterables of ints in 0..n-1")
        lst = []
        for node in it:
            if not isinstance(node, int) or isinstance(node, bool) or not (0 <= node < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")
            lst.append(node)
        defs_lists[k] = lst

    # ---------- graph ----------
    adj = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        pred[v].append(u)

    # ---------- reachable nodes ----------
    reachable = [False] * n
    q = [entry]
    reachable[entry] = True
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # ---------- DFS numbering / spanning tree ----------
    dfs_num = [-1] * n
    dfs_parent = [-1] * n
    vertex = []          # vertex[dfs_num] = node
    stack = [(entry, 0)]
    dfs_num[entry] = 0
    vertex.append(entry)
    dfs_parent[entry] = entry

    while stack:
        u, idx = stack[-1]
        if idx < len(adj[u]):
            v = adj[u][idx]
            stack[-1] = (u, idx + 1)
            if dfs_num[v] == -1:
                dfs_num[v] = len(vertex)
                vertex.append(v)
                dfs_parent[v] = u
                stack.append((v, 0))
        else:
            stack.pop()

    N = len(vertex)

    # ---------- Lengauer-Tarjan dominators ----------
    semi = list(range(n))
    idom = list(range(n))
    ancestor = [-1] * n
    label = list(range(n))
    bucket = [[] for _ in range(n)]

    def eval_(v):
        # iterative path-compressed eval
        if ancestor[v] == -1:
            return label[v]
        path = []
        x = v
        while ancestor[x] != -1:
            path.append(x)
            x = ancestor[x]
        # process from near-root to v
        for x in reversed(path):
            a = ancestor[x]
            if a != -1 and ancestor[a] != -1:
                if dfs_num[semi[label[a]]] < dfs_num[semi[label[x]]]:
                    label[x] = label[a]
                ancestor[x] = ancestor[a]
        return label[v]

    def link(v, w):
        ancestor[w] = v

    # Process vertices in reverse DFS order
    for i in range(N - 1, 0, -1):
        w = vertex[i]
        for v in pred[w]:
            if dfs_num[v] != -1:
                u = eval_(v)
                if dfs_num[semi[u]] < dfs_num[semi[w]]:
                    semi[w] = semi[u]

        bucket[vertex[dfs_num[semi[w]]]].append(w)

        p = dfs_parent[w]
        link(p, w)

        for v in bucket[p]:
            u = eval_(v)
            if dfs_num[semi[u]] < dfs_num[semi[v]]:
                idom[v] = u
            else:
                idom[v] = p
        bucket[p] = []

    for i in range(1, N):
        w = vertex[i]
        if idom[w] != vertex[dfs_num[semi[w]]]:
            idom[w] = idom[idom[w]]
    idom[entry] = entry

    # ---------- dominance frontiers ----------
    DF = [set() for _ in range(n)]

    for b in vertex:
        ib = idom[b]
        for p in pred[b]:
            if not reachable[p]:
                continue
            if b == entry:
                # entry is not strictly dominated by itself, so every incoming
                # reachable edge puts entry into DF(entry)
                DF[entry].add(entry)
            if p == ib:
                continue
            x = p
            while x != ib:
                DF[x].add(b)
                x = idom[x]

    # ---------- iterated dominance frontier for each variable ----------
    result = {}
    for var, lst in defs_lists.items():
        S = [d for d in lst if reachable[d]]
        if not S:
            result[var] = []
            continue

        P = set()
        work = []

        for d in S:
            for y in DF[d]:
                if y not in P:
                    P.add(y)
                    work.append(y)

        while work:
            u = work.pop()
            for v in DF[u]:
                if v not in P:
                    P.add(v)
                    work.append(v)

        result[var] = sorted(P)

    return result

