def round_dec(s, places, mode):
    # ---------- validation ----------
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if isinstance(places, bool) or not isinstance(places, int):
        raise ValueError("places must be an int")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")
    if not isinstance(mode, str) or mode not in (
            "half_even", "half_up", "half_down", "floor", "ceil", "up", "down"
    ):
        raise ValueError("Invalid mode")

    # ---------- split exponent ----------
    epos = -1
    for i, ch in enumerate(s):
        if ch in 'eE':
            if epos != -1:
                raise ValueError("Invalid s")
            epos = i

    if epos != -1:
        mant = s[:epos]
        exp_part = s[epos + 1:]
        if not exp_part:
            raise ValueError("Invalid exponent")
        exp_sign = 1
        if exp_part[0] in '+-':
            if exp_part[0] == '-':
                exp_sign = -1
            exp_part = exp_part[1:]
        if not exp_part or len(exp_part) > 10 or not all(c in '0123456789' for c in exp_part):
            raise ValueError("Invalid exponent")
        exp = exp_sign * int(exp_part)
    else:
        mant = s
        exp = 0

    # ---------- parse mantissa ----------
    sign = 1
    if mant.startswith('+') or mant.startswith('-'):
        if mant[0] == '-':
            sign = -1
        mant = mant[1:]

    if not mant:
        raise ValueError("Invalid s")

    dot = mant.find('.')
    if dot == -1:
        int_part = mant
        frac_part = ""
    else:
        if mant.count('.') != 1:
            raise ValueError("Invalid s")
        int_part = mant[:dot]
        frac_part = mant[dot + 1:]

    digits_all = int_part + frac_part
    if not digits_all or not all(c in '0123456789' for c in digits_all):
        raise ValueError("Invalid digits")

    frac_len = len(frac_part)
    exp_total = exp - frac_len

    # digits without leading zeros; used for magnitude
    dstr = digits_all.lstrip('0') or '0'
    is_zero = all(c == '0' for c in digits_all)

    P = places

    # ---------- rounding magnitude ----------
    # value = sign * int(digits_all) * 10**exp_total
    # Need Q = round(abs(value) * 10**P), an integer.
    shift = exp_total + P

    if is_zero:
        Q = 0
    elif shift >= 0:
        # exact integer: int(digits_all) * 10**shift
        n = len(dstr)
        if n + shift > 4000:
            raise ValueError("Output exceeds 4000 digits")
        Q = int(dstr) * (10 ** shift)
    else:
        k = -shift
        n = len(dstr)

        # magnitude rounding mode:
        # floor and up -> ceil(magnitude)
        # ceil and down -> floor(magnitude)
        # nearest modes use ties
        if mode in ("floor", "up"):
            mag_mode = "ceil"
        elif mode in ("ceil", "down"):
            mag_mode = "floor"
        else:
            mag_mode = "nearest"

        if k >= n:
            # value/10**k is between 0 and 1
            if mag_mode == "ceil":
                Q = 1
            elif mag_mode == "floor":
                Q = 0
            else:  # nearest
                if k > n:
                    Q = 0
                else:
                    # compare digits with half = 5 * 10**(n-1)
                    half = "5" + "0" * (n - 1)
                    if dstr > half:
                        Q = 1
                    elif dstr == half:
                        if mode == "half_up":
                            Q = 1
                        else:  # half_even and half_down tie to even / toward zero
                            Q = 0
                    else:
                        Q = 0
        else:
            # k < n: quotient has n-k digits; remainder is last k digits
            prefix = dstr[:n - k]
            rem_str = dstr[-k:] if k > 0 else ""
            q = int(prefix)

            if mag_mode == "floor":
                Q = q
            elif mag_mode == "ceil":
                Q = q if int(rem_str or 0) == 0 else q + 1
            else:  # nearest
                # compare rem_str with half = 5 followed by k-1 zeros
                half = "5" + "0" * (k - 1)
                if rem_str > half:
                    Q = q + 1
                elif rem_str < half:
                    Q = q
                else:  # exact tie
                    if mode == "half_up":
                        Q = q + 1
                    elif mode == "half_down":
                        Q = q
                    else:  # half_even
                        Q = q if q % 2 == 0 else q + 1

    # ---------- output size check ----------
    if Q == 0:
        if P > 0:
            if P + 1 > 4000:
                raise ValueError("Output exceeds 4000 digits")
        # P <= 0: output is just "0", always within limit
    else:
        d = len(str(Q))
        if P > 0:
            # digits = max(P+1, d)
            if max(P + 1, d) > 4000:
                raise ValueError("Output exceeds 4000 digits")
        else:
            if d + (-P) > 4000:
                raise ValueError("Output exceeds 4000 digits")

    # ---------- format ----------
    if Q == 0:
        if P > 0:
            return "0." + "0" * P
        else:
            return "0"

    if P > 0:
        div = 10 ** P
        int_part = Q // div
        frac_part = Q % div
        out = str(int_part) + "." + str(frac_part).zfill(P)
        if sign < 0:
            out = "-" + out
        return out
    else:
        val = Q * (10 ** (-P))
        out = str(val)
        if sign < 0:
            out = "-" + out
        return out

