        "half_even", "half_up", "half_down", "floor", "ceil", "up", "down"
    ):
        raise ValueError("Invalid mode")

    # ---------- split exponent ----------
    epos = -1
    for i, ch in enumerate(s):
        if ch in 'eE':
            if epos != -1:
                raise ValueError("Invalid s")
            epos = i

    if epos != -1:
        mant = s[:epos]
        exp_part = s[epos + 1:]
        if not exp_part:
            raise ValueError("Invalid exponent")
        exp_sign = 1
        if exp_part[0] in '+-':
            if exp_part[0] == '-':
                exp_sign = -1
            exp_part = exp_part[1:]
        if not exp_part or len(exp_part) > 10 or not all(c in '0123456789' for c in exp_part):
            raise ValueError("Invalid exponent")
        exp = exp_sign * int(exp_part)
    else:
        mant = s
        exp = 0

    # ---------- parse mantissa ----------
    sign = 1
    if mant.startswith('+') or mant.startswith('-'):
        if mant[0] == '-':
            sign = -1
        mant = mant[1:]

    if not mant:
        raise ValueError("Invalid s")

    dot = mant.find('.')
    if dot == -1:
        int_part = mant
        frac_part = ""
    else:
        if mant.count('.') != 1:
            raise ValueError("Invalid s")
        int_part = mant[:dot]
        frac_part = mant[dot + 1:]

    digits_all = int_part + frac_part
    if not digits_all or not all(c in '0123456789' for c in digits_all):
        raise ValueError("Invalid digits")

    frac_len = len(frac_part)
    exp_total = exp - frac_len

    dstr = digits_all.lstrip('0') or '0'
    is_zero = all(c == '0' for c in digits_all)

    P = places

    if is_zero:
        if P > 0:
            return "0." + "0" * P
        else:
            return "0"

    # ---------- rounding ----------
    shift = exp_total + P

    def inc_str(s):
        if s == '0':
            return '1'
        lst = list(s)
        carry = 1
        for i in range(len(lst) - 1, -1, -1):
            if lst[i] == '9':
                lst[i] = '0'
                carry = 1
            else:
                lst[i] = chr(ord(lst[i]) + 1)
                carry = 0
                break
        if carry:
            return '1' + ''.join(lst)
        return ''.join(lst)

    if shift >= 0:
        # exact integer, no rounding needed
        q_len = len(dstr) + shift
        if P > 0:
            if max(P + 1, q_len) > 4000:
                raise ValueError("Output exceeds 4000 digits")
        else:
            if q_len + (-P) > 4000:
                raise ValueError("Output exceeds 4000 digits")
        Q_str = dstr + '0' * shift
    else:
        k = -shift
        n = len(dstr)

        if k >= n:
            q_str = '0'
            if k == n:
                r_str = dstr
                half_str = '5' + '0' * (k - 1)
            else:
                r_str = None
            ceil_ind = 1
        else:
            q_str = dstr[:n - k]
            r_str = dstr[-k:]
            half_str = '5' + '0' * (k - 1)
            ceil_ind = 1 if r_str != '0' * k else 0

        if mode in ("floor", "ceil", "up", "down"):
            if mode == "floor":
                if sign == 1:
                    Q_str = q_str
                else:
                    Q_str = inc_str(q_str) if ceil_ind else q_str
            elif mode == "ceil":
                if sign == 1:
                    Q_str = inc_str(q_str) if ceil_ind else q_str
                else:
                    Q_str = q_str
            elif mode == "up":
                Q_str = inc_str(q_str) if ceil_ind else q_str
            else:  # down
                Q_str = q_str
        else:
            if k >= n and k > n:
                Q_str = q_str
            else:
                if r_str > half_str:
                    Q_str = inc_str(q_str)
                elif r_str < half_str:
                    Q_str = q_str
                else:  # exact tie
                    if mode == "half_up":
                        Q_str = inc_str(q_str)
                    elif mode == "half_down":
                        Q_str = q_str
                    else:  # half_even
                        if q_str[-1] in '02468':
                            Q_str = q_str
                        else:
                            Q_str = inc_str(q_str)

        if P > 0:
            if max(P + 1, len(Q_str)) > 4000:
                raise ValueError("Output exceeds 4000 digits")
        else:
            if Q_str != '0' and len(Q_str) + (-P) > 4000:
                raise ValueError("Output exceeds 4000 digits")

    # ---------- format ----------
    if Q_str == '0':
        if P > 0:
            return "0." + "0" * P
        else:
            return "0"

    if P > 0:
        if len(Q_str) <= P:
            int_part = '0'
            frac = Q_str.zfill(P)
        else:
            int_part = Q_str[:-P]
            frac = Q_str[-P:]
        out = int_part + '.' + frac
        if sign < 0:
            out = '-' + out
        return out
    else:
        out = Q_str + '0' * (-P)
        if sign < 0:
            out = '-' + out
        return out

