def round_dec(s, places, mode):
    # ---------- parameter validation ----------
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if isinstance(places, bool) or not isinstance(places, int):
        raise ValueError("places must be an int")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")
    if mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("invalid mode")

    # ---------- parse exponent ----------
    exp = 0
    exp_pos = -1
    for idx, ch in enumerate(s):
        if ch in "eE":
            if exp_pos != -1:
                raise ValueError("invalid s")
            exp_pos = idx

    if exp_pos != -1:
        exp_str = s[exp_pos + 1:]
        if not exp_str:
            raise ValueError("invalid exponent")
        esign = 1
        j = 0
        if exp_str[0] in "+-":
            if exp_str[0] == "-":
                esign = -1
            j = 1
        edigits = exp_str[j:]
        if not edigits or not (1 <= len(edigits) <= 10):
            raise ValueError("invalid exponent")
        if not all('0' <= c <= '9' for c in edigits):
            raise ValueError("invalid exponent")
        exp = esign * int(edigits)
        mant = s[:exp_pos]
    else:
        mant = s

    # ---------- parse mantissa ----------
    if not mant:
        raise ValueError("invalid s")

    sign = 1
    if mant[0] in "+-":
        if mant[0] == "-":
            sign = -1
        mant = mant[1:]
        if not mant:
            raise ValueError("invalid s")

    if mant.count(".") > 1:
        raise ValueError("invalid s")

    dot = mant.find(".")
    if dot == -1:
        int_part = mant
        frac_part = ""
    else:
        int_part = mant[:dot]
        frac_part = mant[dot + 1:]

    if not int_part and not frac_part:
        raise ValueError("invalid s")
    if not all('0' <= c <= '9' for c in int_part + frac_part):
        raise ValueError("invalid s")

    digits_all = int_part + frac_part
    digits = digits_all.lstrip('0') or '0'
    frac_len = len(frac_part)
    E0 = exp - frac_len          # value = int(digits) * 10**E0

    # ---------- rounding ----------
    delta = E0 + places          # value / 10**(-places) = digits * 10**delta

    if delta >= 0:
        # Exact multiple: quotient is digits * 10**delta
        if digits == "0":
            q_mag = "0"
        else:
            q_mag = digits + "0" * delta
        neg = sign < 0
    else:
        k = -delta               # round digits / 10**k
        n = len(digits)

        # floor quotient and remainder
        if k >= n:
            q_floor = "0"
            rem = digits
        else:
            q_floor = digits[:n - k]
            rem = digits[n - k:]

        # compare remainder with half = 5 * 10**(k-1)
        rem_val = rem.lstrip('0') or '0'
        rlen = len(rem_val)
        if rem_val == "0":
            cmp_half = -1        # less than half
        elif rlen < k:
            cmp_half = -1        # less than half
        elif rlen > k:
            cmp_half = 1         # impossible, but safe
        else:
            if rem_val[0] < '5':
                cmp_half = -1
            elif rem_val[0] > '5':
                cmp_half = 1
            else:
                if all(c == '0' for c in rem_val[1:]):
                    cmp_half = 0
                else:
                    cmp_half = 1

        # increment helper
        def inc(sval):
            if not sval:
                return "1"
            lst = list(sval)
            i = len(lst) - 1
            while i >= 0 and lst[i] == '9':
                lst[i] = '0'
                i -= 1
            if i < 0:
                return "1" + "".join(lst)
            lst[i] = chr(ord(lst[i]) + 1)
            return "".join(lst)

        exact = (rem_val == "0")

        if mode in ("half_even", "half_up", "half_down"):
            if exact or cmp_half < 0:
                mag = q_floor
            elif cmp_half > 0:
                mag = inc(q_floor)
            else:  # exact tie
                if mode == "half_up":
                    mag = inc(q_floor)
                elif mode == "half_down":
                    mag = q_floor
                else:  # half_even
                    if int(q_floor) % 2 == 0:
                        mag = q_floor
                    else:
                        mag = inc(q_floor)
        else:
            ceil_mag = q_floor if exact else inc(q_floor)
            floor_mag = q_floor

            if mode == "floor":
                mag = ceil_mag if sign < 0 else floor_mag
            elif mode == "ceil":
                mag = floor_mag if sign < 0 else ceil_mag
            elif mode == "up":
                mag = ceil_mag
            else:  # down
                mag = floor_mag

        neg = sign < 0 and mag != "0"
        q_mag = mag

    # ---------- size check and formatting ----------
    if places > 0:
        # Split q_mag into integer and fractional parts.
        if q_mag == "0":
            int_str = "0"
            frac_str = "0" * places
        elif len(q_mag) <= places:
            int_str = "0"
            frac_str = q_mag.rjust(places, '0')
        else:
            int_str = q_mag[:-places]
            frac_str = q_mag[-places:]
        total_digits = len(int_str) + places
        if total_digits > 4000:
            raise ValueError("output too large")
        out = (("-" if neg else "") + int_str + "." + frac_str)
    elif places == 0:
        if q_mag == "0":
            out = "0"
        else:
            out = ("-" if neg else "") + q_mag
    else:
        # places < 0: append -places zeros
        if q_mag == "0":
            out = "0"
        else:
            total_digits = len(q_mag) + (-places)
            if total_digits > 4000:
                raise ValueError("output too large")
            out = ("-" if neg else "") + q_mag + "0" * (-places)

    return out

