import bisect

def _is_leap(y):
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _days_in_month(y, m):
    if m == 2:
        return 29 if _is_leap(y) else 28
    if m in (4, 6, 9, 11):
        return 30
    return 31

def _last_day_of_month(y, m):
    return _days_in_month(y, m)

def _count_leaps_upto(n):
    return n // 4 - n // 100 + n // 400

def _days_from_epoch(y, m, d):
    """Days from 1970-01-01 to date (date itself has index 0)."""
    years = y - 1970
    days = years * 365
    days += _count_leaps_upto(y - 1) - _count_leaps_upto(1969)
    for i in range(1, m):
        days += _days_in_month(y, i)
    days += d - 1
    return days

def _days_to_date(days):
    """Efficient inverse of _days_from_epoch for days >= 0."""
    # Binary search for year: find first y with Jan1(y) > days
    lo, hi = 1970, 10000
    while lo < hi:
        mid = (lo + hi) // 2
        if _days_from_epoch(mid, 1, 1) <= days:
            lo = mid + 1
        else:
            hi = mid
    y = lo - 1
    day_of_year = days - _days_from_epoch(y, 1, 1)
    m = 1
    for m in range(1, 13):
        dim = _days_in_month(y, m)
        if day_of_year < dim:
            break
        day_of_year -= dim
    d = day_of_year + 1
    return y, m, d

def _prev_day(y, m, d):
    if d > 1:
        return y, m, d - 1
    if m > 1:
        m -= 1
        return y, m, _last_day_of_month(y, m)
    return y - 1, 12, 31

def _next_day(y, m, d):
    dim = _last_day_of_month(y, m)
    if d < dim:
        return y, m, d + 1
    if m < 12:
        return y, m + 1, 1
    return y + 1, 1, 1

def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be list or tuple")
    if len(leaps) > 200:
        raise ValueError("leaps has too many entries")
    prev = None
    for entry in leaps:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("Each leap entry must be a list/tuple of 3 ints")
        y, m, delta = entry
        if type(y) is not int or type(m) is not int or type(delta) is not int:
            raise ValueError("Leap entries must contain ints")
        if not (1970 <= y <= 9998):
            raise ValueError("Year out of range")
        if not (1 <= m <= 12):
            raise ValueError("Month out of range")
        if delta not in (1, -1):
            raise ValueError("Delta must be 1 or -1")
        curr = (y, m)
        if prev is not None and curr <= prev:
            raise ValueError("Leaps must be strictly increasing")
        prev = curr

def _build_leap_data(leaps):
    leap_dates = []
    leap_offsets = [0]  # offset before first leap day
    leap_lengths = {}
    for y, m, delta in leaps:
        d = _last_day_of_month(y, m)
        date = (y, m, d)
        leap_dates.append(date)
        leap_offsets.append(leap_offsets[-1] + delta)
        leap_lengths[date] = 86400 + delta
    return leap_dates, leap_offsets, leap_lengths

def _get_offset(date_tuple, leap_dates, leap_offsets):
    idx = bisect.bisect_left(leap_dates, date_tuple)
    return leap_offsets[idx]

def leap_label(n, leaps):
    if type(n) is not int or isinstance(n, bool):
        raise ValueError("n must be int >= 0")
    if n < 0:
        raise ValueError("n must be >= 0")
    _validate_leaps(leaps)

    leap_dates, leap_offsets, leap_lengths = _build_leap_data(leaps)

    approx_days = n // 86400
    y, m, d = _days_to_date(approx_days)
    if y > 9999:
        raise ValueError("Year exceeds 9999")

    while True:
        date_tuple = (y, m, d)
        start_sec = _days_from_epoch(y, m, d) * 86400 + _get_offset(date_tuple, leap_dates, leap_offsets)
        length = leap_lengths.get(date_tuple, 86400)

        if n < start_sec:
            y, m, d = _prev_day(y, m, d)
        elif n >= start_sec + length:
            y, m, d = _next_day(y, m, d)
        else:
            break

        if y > 9999:
            raise ValueError("Year exceeds 9999")
        if y < 1970:
            raise ValueError("Before epoch")

    time_sec = n - start_sec
    h = time_sec // 3600
    rem = time_sec % 3600
    mi = rem // 60
    s = rem % 60
    return f"{y:04d}-{m:02d}-{d:02d} {h:02d}:{mi:02d}:{s:02d}"

def leap_count(label, leaps):
    if not isinstance(label, str) or len(label) != 19:
        raise ValueError("Invalid label format")
    for pos in (4, 7, 10, 13, 16):
        expected = '-' if pos in (4, 7) else (' ' if pos == 10 else ':')
        if label[pos] != expected:
            raise ValueError("Invalid label format")
    for i in range(19):
        if i in (4, 7, 10, 13, 16):
            continue
        if not ('0' <= label[i] <= '9'):
            raise ValueError("Invalid label format")

    y = int(label[0:4])
    m = int(label[5:7])
    d = int(label[8:10])
    h = int(label[11:13])
    mi = int(label[14:16])
    s = int(label[17:19])

    if not (1970 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")
    dim = _last_day_of_month(y, m)
    if not (1 <= d <= dim):
        raise ValueError("Day out of range")
    if not (0 <= h <= 23):
        raise ValueError("Hour out of range")
    if not (0 <= mi <= 59):
        raise ValueError("Minute out of range")
    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    _validate_leaps(leaps)
    leap_dates, leap_offsets, leap_lengths = _build_leap_data(leaps)

    date_tuple = (y, m, d)
    length = leap_lengths.get(date_tuple, 86400)
    time_sec = h * 3600 + mi * 60 + s

    if s == 60:
        if h != 23 or mi != 59:
            raise ValueError("Second 60 only allowed at 23:59:60")
        if length != 86401:
            raise ValueError("23:59:60 only on a +1 leap day")

    if time_sec >= length:
        raise ValueError("Label does not exist on its day")

    days_count = _days_from_epoch(y, m, d)
    offset = _get_offset(date_tuple, leap_dates, leap_offsets)
    return days_count * 86400 + offset + time_sec

import bisect

def _is_leap(y):
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _days_in_month(y, m):
    if m == 2:
        return 29 if _is_leap(y) else 28
    if m in (4, 6, 9, 11):
        return 30
    return 31

def _last_day_of_month(y, m):
    return _days_in_month(y, m)

def _count_leaps_upto(n):
    return n // 4 - n // 100 + n // 400

def _days_from_epoch(y, m, d):
    """Days from 1970-01-01 to date (date itself has index 0)."""
    years = y - 1970
    days = years * 365
    days += _count_leaps_upto(y - 1) - _count_leaps_upto(1969)
    for i in range(1, m):
        days += _days_in_month(y, i)
    days += d - 1
    return days

def _days_to_date(days):
    """Efficient inverse of _days_from_epoch for days >= 0."""
    lo, hi = 1970, 10000
    while lo < hi:
        mid = (lo + hi) // 2
        if _days_from_epoch(mid, 1, 1) <= days:
            lo = mid + 1
        else:
            hi = mid
    y = lo - 1
    day_of_year = days - _days_from_epoch(y, 1, 1)
    m = 1
    for m in range(1, 13):
        dim = _days_in_month(y, m)
        if day_of_year < dim:
            break
        day_of_year -= dim
    d = day_of_year + 1
    return y, m, d

def _prev_day(y, m, d):
    if d > 1:
        return y, m, d - 1
    if m > 1:
        m -= 1
        return y, m, _last_day_of_month(y, m)
    return y - 1, 12, 31

def _next_day(y, m, d):
    dim = _last_day_of_month(y, m)
    if d < dim:
        return y, m, d + 1
    if m < 12:
        return y, m + 1, 1
    return y + 1, 1, 1

def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be list or tuple")
    if len(leaps) > 200:
        raise ValueError("leaps has too many entries")
    prev = None
    for entry in leaps:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("Each leap entry must be a list/tuple of 3 ints")
        y, m, delta = entry
        if type(y) is not int or type(m) is not int or type(delta) is not int:
            raise ValueError("Leap entries must contain ints")
        if not (1970 <= y <= 9998):
            raise ValueError("Year out of range")
        if not (1 <= m <= 12):
            raise ValueError("Month out of range")
        if delta not in (1, -1):
            raise ValueError("Delta must be 1 or -1")
        curr = (y, m)
        if prev is not None and curr <= prev:
            raise ValueError("Leaps must be strictly increasing")
        prev = curr

def _build_leap_data(leaps):
    leap_dates = []
    leap_offsets = [0]  # offset before first leap day
    leap_lengths = {}
    for y, m, delta in leaps:
        d = _last_day_of_month(y, m)
        date = (y, m, d)
        leap_dates.append(date)
        leap_offsets.append(leap_offsets[-1] + delta)
        leap_lengths[date] = 86400 + delta
    return leap_dates, leap_offsets, leap_lengths

def _get_offset(date_tuple, leap_dates, leap_offsets):
    idx = bisect.bisect_left(leap_dates, date_tuple)
    return leap_offsets[idx]

def leap_label(n, leaps):
    _validate_leaps(leaps)
    if type(n) is not int or isinstance(n, bool):
        raise ValueError("n must be int >= 0")
    if n < 0:
        raise ValueError("n must be >= 0")

    leap_dates, leap_offsets, leap_lengths = _build_leap_data(leaps)

    approx_days = n // 86400
    y, m, d = _days_to_date(approx_days)
    if y > 9999:
        raise ValueError("Year exceeds 9999")

    while True:
        date_tuple = (y, m, d)
        start_sec = _days_from_epoch(y, m, d) * 86400 + _get_offset(date_tuple, leap_dates, leap_offsets)
        length = leap_lengths.get(date_tuple, 86400)

        if n < start_sec:
            y, m, d = _prev_day(y, m, d)
        elif n >= start_sec + length:
            y, m, d = _next_day(y, m, d)
        else:
            break

        if y > 9999:
            raise ValueError("Year exceeds 9999")
        if y < 1970:
            raise ValueError("Before epoch")

    time_sec = n - start_sec

    # Handle the extra second at 23:59:60 on a +1 leap day.
    if time_sec == 86400 and length == 86401:
        h, mi, s = 23, 59, 60
    else:
        h = time_sec // 3600
        rem = time_sec % 3600
        mi = rem // 60
        s = rem % 60

    return f"{y:04d}-{m:02d}-{d:02d} {h:02d}:{mi:02d}:{s:02d}"

def leap_count(label, leaps):
    _validate_leaps(leaps)

    if not isinstance(label, str) or len(label) != 19:
        raise ValueError("Invalid label format")
    for pos in (4, 7, 10, 13, 16):
        expected = '-' if pos in (4, 7) else (' ' if pos == 10 else ':')
        if label[pos] != expected:
            raise ValueError("Invalid label format")
    for i in range(19):
        if i in (4, 7, 10, 13, 16):
            continue
        if not ('0' <= label[i] <= '9'):
            raise ValueError("Invalid label format")

    y = int(label[0:4])
    m = int(label[5:7])
    d = int(label[8:10])
    h = int(label[11:13])
    mi = int(label[14:16])
    s = int(label[17:19])

    if not (1970 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")
    dim = _last_day_of_month(y, m)
    if not (1 <= d <= dim):
        raise ValueError("Day out of range")
    if not (0 <= h <= 23):
        raise ValueError("Hour out of range")
    if not (0 <= mi <= 59):
        raise ValueError("Minute out of range")
    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    leap_dates, leap_offsets, leap_lengths = _build_leap_data(leaps)

    date_tuple = (y, m, d)
    length = leap_lengths.get(date_tuple, 86400)
    time_sec = h * 3600 + mi * 60 + s

    if s == 60:
        if h != 23 or mi != 59:
            raise ValueError("Second 60 only allowed at 23:59:60")
        if length != 86401:
            raise ValueError("23:59:60 only on a +1 leap day")

    if time_sec >= length:
        raise ValueError("Label does not exist on its day")

    days_count = _days_from_epoch(y, m, d)
    offset = _get_offset(date_tuple, leap_dates, leap_offsets)
    return days_count * 86400 + offset + time_sec

def list_schedule(jobs, workers):
    # --- Validation ---
    if not isinstance(workers, int) or isinstance(workers, bool) or not (1 <= workers <= 64):
        raise ValueError("Invalid workers")
    if not isinstance(jobs, (list, tuple)):
        raise ValueError("Invalid jobs type")
    if len(jobs) > 200:
        raise ValueError("Too many jobs")

    job_data = {}
    names = set()

    # First pass: collect names, check basic types and structure
    for job in jobs:
        if not isinstance(job, (tuple, list)) or len(job) != 3:
            raise ValueError("Invalid job format")
        name, duration, deps = job
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid job name")
        names.add(name)

        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("Invalid duration type")
        if not (0 <= duration <= 10**12):
            raise ValueError("Invalid duration range")

        if not isinstance(deps, (list, tuple)):
            raise ValueError("Invalid deps type")
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("Dep is not a string")

        job_data[name] = (duration, deps)

    if len(names) != len(job_data):
        raise ValueError("Duplicate job name")

    # Second pass: check deps existence, self-deps, repeated deps
    adj = {}
    for name, (dur, deps) in job_data.items():
        if len(set(deps)) != len(deps):
            raise ValueError("Repeated dependencies")
        for d in deps:
            if d not in names:
                raise ValueError("Unknown dependency")
            if d == name:
                raise ValueError("Self-dependency")
        adj[name] = deps

    # Cycle detection
    visited = set()
    rec_stack = set()

    def dfs_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for dep in adj[node]:
            if dep not in visited:
                if dfs_cycle(dep):
                    return True
            elif dep in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    for name in names:
        if name not in visited:
            if dfs_cycle(name):
                raise ValueError("Dependency cycle")

    # --- Priority Calculation ---
    # forward_deps[j] contains jobs that depend on j
    forward_deps = {name: [] for name in names}
    for name, (_, deps) in job_data.items():
        for d in deps:
            forward_deps[d].append(name)

    priority = {}

    def calc_priority(j):
        if j in priority:
            return priority[j]
        max_succ = 0
        for s in forward_deps[j]:
            max_succ = max(max_succ, calc_priority(s))
        priority[j] = job_data[j][0] + max_succ
        return priority[j]

    for j in names:
        calc_priority(j)

    # --- Simulation ---
    if not names:
        return {"start": {}, "worker": {}, "makespan": 0}

    remaining_deps = {j: len(job_data[j][1]) for j in names}
    ready_jobs = [j for j in names if remaining_deps[j] == 0]
    running = {}  # worker -> (job_name, finish_time)
    start_times = {}
    worker_map = {}
    time = 0

    while len(start_times) < len(names):
        # Finish jobs that complete at current time
        finish_now = [(w, j) for w, (j, ft) in running.items() if ft == time]
        for w, j in finish_now:
            del running[w]
            for dep in forward_deps[j]:
                remaining_deps[dep] -= 1
                if remaining_deps[dep] == 0:
                    ready_jobs.append(dep)

        # Sort ready jobs by priority (desc), then name (asc)
        ready_jobs.sort(key=lambda j: (-priority[j], j))

        # Assign ready jobs to lowest-numbered idle workers
        idle_workers = sorted(set(range(workers)) - set(running.keys()))
        while ready_jobs and idle_workers:
            j = ready_jobs.pop(0)
            w = idle_workers[0]  # lowest-numbered idle worker, don't remove yet
            dur = job_data[j][0]

            start_times[j] = time
            worker_map[j] = w

            if dur == 0:
                # Zero-duration jobs finish immediately, freeing the worker instantly
                for dep in forward_deps[j]:
                    remaining_deps[dep] -= 1
                    if remaining_deps[dep] == 0:
                        ready_jobs.append(dep)
                # Re-sort to account for newly ready jobs at the same time instant
                ready_jobs.sort(key=lambda j: (-priority[j], j))
                # Worker remains idle, so idle_workers list unchanged (w not removed)
            else:
                # Remove the worker from idle list because it becomes busy
                idle_workers.pop(0)
                running[w] = (j, time + dur)

        # Advance time to next event
        if running:
            time = min(ft for _, ft in running.values())
        else:
            # Should not be reachable for valid DAG inputs
            break

    makespan = max(start_times[j] + job_data[j][0] for j in start_times)
    return {"start": start_times, "worker": worker_map, "makespan": makespan}

def list_schedule(jobs, workers):
    # ---------- validation ----------
    if not isinstance(workers, int) or isinstance(workers, bool) or not (1 <= workers <= 64):
        raise ValueError("Invalid workers")

    if not isinstance(jobs, (list, tuple)):
        raise ValueError("Invalid jobs type")
    if len(jobs) > 200:
        raise ValueError("Too many jobs")

    job_data = {}
    seen_names = set()

    for job in jobs:
        if not isinstance(job, tuple) or len(job) != 3:
            raise ValueError("Invalid job format")
        name, duration, deps = job

        if not isinstance(name, str) or name == "":
            raise ValueError("Invalid job name")
        if name in seen_names:
            raise ValueError("Duplicate job name")
        seen_names.add(name)

        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("Invalid duration type")
        if not (0 <= duration <= 10**12):
            raise ValueError("Invalid duration range")

        if not isinstance(deps, (list, tuple)):
            raise ValueError("Invalid deps type")
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("Dep is not a string")

        if len(set(deps)) != len(deps):
            raise ValueError("Repeated dependencies")

        for d in deps:
            if d == name:
                raise ValueError("Self-dependency")

        job_data[name] = (duration, tuple(deps))

    # Unknown dependencies
    for name, (_, deps) in job_data.items():
        for d in deps:
            if d not in seen_names:
                raise ValueError("Unknown dependency")

    if not job_data:
        return {"start": {}, "worker": {}, "makespan": 0}

    # ---------- cycle detection ----------
    adj = {name: deps for name, (_, deps) in job_data.items()}
    visited = set()
    rec_stack = set()

    def dfs_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for dep in adj[node]:
            if dep not in visited:
                if dfs_cycle(dep):
                    return True
            elif dep in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    for name in seen_names:
        if name not in visited:
            if dfs_cycle(name):
                raise ValueError("Dependency cycle")

    # ---------- priority ----------
    # forward_deps[j] = jobs that depend on j
    forward_deps = {name: [] for name in seen_names}
    for name, (_, deps) in job_data.items():
        for d in deps:
            forward_deps[d].append(name)

    priority = {}

    def calc_priority(j):
        if j in priority:
            return priority[j]
        best_successor = 0
        for succ in forward_deps[j]:
            best_successor = max(best_successor, calc_priority(succ))
        priority[j] = job_data[j][0] + best_successor
        return priority[j]

    for name in seen_names:
        calc_priority(name)

    # ---------- simulation ----------
    remaining_deps = {name: len(job_data[name][1]) for name in seen_names}
    ready = [name for name in seen_names if remaining_deps[name] == 0]
    running = {}          # worker -> (job, finish_time)
    start_times = {}
    worker_map = {}
    time = 0
    scheduled = 0

    while scheduled < len(seen_names):
        # Finish jobs whose finish time is current time
        finished_workers = list(running.keys())
        for w in finished_workers:
            job, ft = running[w]
            if ft == time:
                del running[w]
                for succ in forward_deps[job]:
                    remaining_deps[succ] -= 1
                    if remaining_deps[succ] == 0:
                        ready.append(succ)

        # Start as many ready jobs as possible at this instant
        idle_workers = sorted(set(range(workers)) - set(running.keys()))

        while ready and idle_workers:
            ready.sort(key=lambda j: (-priority[j], j))
            job = ready.pop(0)
            duration = job_data[job][0]
            w = idle_workers[0]

            start_times[job] = time
            worker_map[job] = w
            scheduled += 1

            if duration == 0:
                # Finishes at the same instant; worker remains idle
                for succ in forward_deps[job]:
                    remaining_deps[succ] -= 1
                    if remaining_deps[succ] == 0:
                        ready.append(succ)
            else:
                idle_workers.pop(0)
                running[w] = (job, time + duration)

        if scheduled == len(seen_names):
            break

        if not running:
            # Validated DAGs are schedulable; this should not be reached.
            break

        time = min(ft for _, ft in running.values())

    makespan = max(start_times[j] + job_data[j][0] for j in seen_names)
    return {"start": start_times, "worker": worker_map, "makespan": makespan}
